function escapeRegex(s: string): string {
  return s.replace(/[.*+?^$${}()|[\]\\]/g, "\\$&");
}

let cachedRegex: RegExp | null = null;
let cachedMap: Map<string, string> | null = null;

export function getN5FuriganaRegex(): { regex: RegExp; map: Map<string, string> } {
  if (!cachedRegex || !cachedMap) {
    cachedMap = new Map(N5_FURIGANA_ENTRIES.map(e => [e.original, e.pattern]));
    const patternStr = N5_FURIGANA_ENTRIES.map(e => escapeRegex(e.original)).join("|");
    cachedRegex = new RegExp(patternStr, "g");
  }
  return { regex: cachedRegex, map: cachedMap };
}

export function autoAnnotateFurigana(text: string): string {
  if (!text || !/[\u4e00-\u9faf]/.test(text)) return text;
  // If text already has [kanji]{reading} format, avoid re-annotating inside brackets
  if (text.includes("[") && text.includes("]{")) return text;
  
  const { regex, map } = getN5FuriganaRegex();
  // Reset lastIndex for stateful global regex
  regex.lastIndex = 0;
  return text.replace(regex, match => map.get(match) ?? match);
}
